import{_ as o,a}from"./chunks/section-page-relation-fr-dark.BHUNTUFU.js";import{_ as r,a as i}from"./chunks/singleton-vs-collection-fr-dark.Ct0pYYEx.js";import{_ as l,m as d,k as c,ah as n,q as e,B as s}from"./chunks/framework.HEc25T99.js";const k=JSON.parse('{"title":"Concepts de base","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/getting-started/core-concepts.md","filePath":"src/fr/developers/getting-started/core-concepts.md"}'),u={name:"fr/developers/getting-started/core-concepts.md"},p=o+"#light-only",m=a+"#dark-only",h=r+"#light-only",g=i+"#dark-only";function _(f,t,b,q,x,L){return c(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="concepts-de-base" tabindex="-1">Concepts de base <a class="header-anchor" href="#concepts-de-base" aria-label="Permalink to &quot;Concepts de base&quot;">​</a></h1><h2 id="les-sections" tabindex="-1">Les sections <a class="header-anchor" href="#les-sections" aria-label="Permalink to &quot;Les sections&quot;">​</a></h2><p>L&#39;élément de base de Creopse est la section, elle peut être définie comme un bloc de contenu contextualisé et localisé. Toute section possède une structure de données permettant d&#39;organiser son contenu et des paramètres permettant d&#39;adapter son rendu. Voir <a href="./../development/sections-widgets.html">Sections &amp; Widgets</a> pour le détail de leur création et de leur structure.</p><h2 id="les-widgets" tabindex="-1">Les widgets <a class="header-anchor" href="#les-widgets" aria-label="Permalink to &quot;Les widgets&quot;">​</a></h2><p>Un widget est un bloc d&#39;interface statique, sans structure de données ni contenu géré depuis l&#39;administration — un préchargeur ou une barre de progression de scroll, par exemple. Contrairement à une section, il n&#39;est ni éditable ni traduisible. Voir <a href="./../development/sections-widgets.html#widgets">Sections &amp; Widgets</a>.</p><h2 id="les-pages" tabindex="-1">Les pages <a class="header-anchor" href="#les-pages" aria-label="Permalink to &quot;Les pages&quot;">​</a></h2><p>Les pages dans Creopse sont des empilements de sections dont on peut modifier la position et le contenu. Chaque page peut comporter autant de sections que nécessaire, et le contenu de chacune est lié à la page sur laquelle elle se trouve. Une même section peut ainsi être utilisée sur plusieurs pages avec des contenus différents, ou apparaître plusieurs fois sur une même page. Il est également possible de lier le contenu d&#39;une section à son contenu sur une autre page. Voir <a href="./../development/pages.html">Pages</a> pour le détail des commandes et des cas d&#39;usage.</p>',7),e("p",null,[e("img",{src:p,alt:"Section / Page relation"}),e("img",{src:m,alt:"Section / Page relation"})],-1),n('<h2 id="les-menus" tabindex="-1">Les menus <a class="header-anchor" href="#les-menus" aria-label="Permalink to &quot;Les menus&quot;">​</a></h2><p>Un menu regroupe les liens de navigation d&#39;un emplacement donné (header, footer...). Les composants comme le Header ou le Footer ne font qu&#39;afficher les items définis par ce système plutôt que des liens codés en dur, ce qui permet de gérer la navigation depuis l&#39;administration sans toucher au code. Voir <a href="./../development/menus.html">Menus</a>.</p><h2 id="les-modeles-de-contenu" tabindex="-1">Les modèles de contenu <a class="header-anchor" href="#les-modeles-de-contenu" aria-label="Permalink to &quot;Les modèles de contenu&quot;">​</a></h2><p>Les modèles de contenu sont des modèles de données qui permettent de récupérer du contenu lié au contexte métier de la plateforme et qui peut être utilisé un peu partout, par exemple des services, des articles, des produits, etc. Ils sont accessibles depuis n&#39;importe quelle section de n&#39;importe quelle page. Voir <a href="./../development/content-models.html">Modèles de contenu</a>.</p><h2 id="les-permaliens" tabindex="-1">Les permaliens <a class="header-anchor" href="#les-permaliens" aria-label="Permalink to &quot;Les permaliens&quot;">​</a></h2><p>Un permalien associe un préfixe d&#39;URL public à un contenu — un item de modèle de contenu, ou un article/catégorie/tag de news — et à la page qui le rend. Sans permalien, un modèle de contenu n&#39;a pas de page de détail accessible, même si celle-ci est déjà codée. Voir <a href="./../development/permalinks.html">Permaliens</a>.</p><h2 id="les-structures-de-donnees" tabindex="-1">Les structures de données <a class="header-anchor" href="#les-structures-de-donnees" aria-label="Permalink to &quot;Les structures de données&quot;">​</a></h2><p>Les structures de données sont des descriptions de la forme des données qui constituent le contenu de divers éléments comme les sections et les modèles de contenu. Elles permettent à Creopse de générer les champs nécessaires pour récupérer les données constituant le contenu dans l&#39;interface d&#39;administration.</p><p>On distingue deux types de composantes dans les structures de données :</p><ul><li><strong>Les singletons</strong> :</li></ul><p>Ce sont des composantes qui permettent de récupérer des données de contenus simples, par exemple un titre, une image, un texte, etc.</p><ul><li><strong>Les collections</strong> :</li></ul><p>Ce sont des composantes qui permettent de récupérer des données de contenus complexes et répétitifs, par exemple une liste de membres d&#39;équipe, une liste de témoignages clients, etc.</p>',13),e("p",null,[e("img",{src:h,alt:"Singleton vs Collection"}),e("img",{src:g,alt:"Singleton vs Collection"})],-1),e("p",null,[s("Voir "),e("a",{href:"./../development/sections-widgets.html#types-de-champs"},"Types de champs"),s(" pour la liste complète des types disponibles, et "),e("a",{href:"./../development/utilities.html"},"Utilitaires"),s(" pour les composables/hooks qui consomment ces données dans un composant.")],-1)])])}const S=l(u,[["render",_]]);export{k as __pageData,S as default};
